//! Rich's `Segment` helpers and `Control` escapes compared with Python
//! Rich 15, using `tests/fixtures/segment.golden` (generated by
//! `scripts/gen_segment_golden.py`). Rich's `Segment` is fast-rich's
//! `Span`; a line is a `Vec<Span>`.

use fast_rich::console::Console;
use fast_rich::control::{escape_control_codes, strip_control_codes, Control, ControlCode};
use fast_rich::renderable::Segment;
use fast_rich::style::{Color, Style};
use fast_rich::text::Span;

const GOLDEN: &str = include_str!("fixtures/segment.golden");

fn unhex(hex: &str) -> String {
    let bytes: Vec<u8> = (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
        .collect();
    String::from_utf8(bytes).unwrap()
}

fn hex(s: &str) -> String {
    s.bytes().map(|b| format!("{b:02x}")).collect()
}

// ---- style descriptions (see scripts/gen_ansi_golden.py) ----------------

fn color_desc(color: Color) -> String {
    let named = [
        Color::Black,
        Color::Red,
        Color::Green,
        Color::Yellow,
        Color::Blue,
        Color::Magenta,
        Color::Cyan,
        Color::White,
        Color::BrightBlack,
        Color::BrightRed,
        Color::BrightGreen,
        Color::BrightYellow,
        Color::BrightBlue,
        Color::BrightMagenta,
        Color::BrightCyan,
        Color::BrightWhite,
    ];
    match color {
        Color::Default => "default".into(),
        Color::Ansi256(n) => n.to_string(),
        Color::Rgb { r, g, b } => format!("#{r:02x}{g:02x}{b:02x}"),
        c => named.iter().position(|n| *n == c).unwrap().to_string(),
    }
}

fn style_desc(style: &Style, link: Option<&str>) -> String {
    let mut words: Vec<String> = Vec::new();
    let attrs = style.to_string();
    if !attrs.is_empty() {
        words.push(attrs);
    }
    if let Some(c) = style.foreground {
        words.push(format!("fg={}", color_desc(c)));
    }
    if let Some(c) = style.background {
        words.push(format!("bg={}", color_desc(c)));
    }
    if let Some(url) = link {
        words.push(format!("link={url}"));
    }
    words.join(" ")
}

fn parse_color(s: &str) -> Color {
    if let Ok(n) = s.parse::<u8>() {
        Color::Ansi256(n)
    } else {
        Color::parse(s).unwrap()
    }
}

/// Style and link from a description.
fn parse_desc(desc: &str) -> (Style, Option<String>) {
    let mut style = Style::new();
    let mut link = None;
    // A link may contain spaces only after `link=`, which comes last.
    let (head, url) = match desc.find("link=") {
        Some(i) => (&desc[..i], Some(desc[i + 5..].to_string())),
        None => (desc, None),
    };
    if url.is_some() {
        link = url;
    }
    for word in head.split_whitespace() {
        if let Some(c) = word.strip_prefix("fg=") {
            style.foreground = Some(parse_color(c));
        } else if let Some(c) = word.strip_prefix("bg=") {
            style.background = Some(parse_color(c));
        } else {
            style = style.combine(&Style::parse(word));
        }
    }
    (style, link)
}

fn style_arg(arg: &str) -> Style {
    if arg == "-" {
        Style::new()
    } else {
        parse_desc(&unhex(arg)).0
    }
}

// ---- segment encoding ----------------------------------------------------

fn enc_span(span: &Span) -> String {
    format!(
        "{}.{}.{}",
        hex(&span.text),
        hex(&style_desc(&span.style, span.link.as_deref())),
        u8::from(span.is_control())
    )
}

fn enc_spans(spans: &[Span]) -> String {
    let parts: Vec<String> = spans.iter().map(enc_span).collect();
    format!("[{}]", parts.join(","))
}

fn enc_lines(lines: &[Vec<Span>]) -> String {
    let parts: Vec<String> = lines.iter().map(|l| enc_spans(l)).collect();
    format!("{{{}}}", parts.concat())
}

fn dec_spans(s: &str) -> Vec<Span> {
    let inner = s.strip_prefix('[').unwrap().strip_suffix(']').unwrap();
    if inner.is_empty() {
        return Vec::new();
    }
    inner
        .split(',')
        .map(|seg| {
            let f: Vec<&str> = seg.split('.').collect();
            let (style, link) = parse_desc(&unhex(f[1]));
            let span = Span {
                text: unhex(f[0]).into(),
                style,
                link,
            };
            assert_eq!(span.is_control(), f[2] == "1", "control flag of {seg}");
            span
        })
        .collect()
}

fn dec_lines(s: &str) -> Vec<Vec<Span>> {
    let inner = s.strip_prefix('{').unwrap().strip_suffix('}').unwrap();
    inner.split_inclusive(']').map(dec_spans).collect()
}

fn flag(s: &str) -> bool {
    s == "1"
}

fn control(args: &str) -> Control {
    let w: Vec<&str> = args.split(' ').collect();
    let int = |i: usize| w[i].parse::<i64>().unwrap();
    match w[0] {
        "bell" => Control::bell(),
        "home" => Control::home(),
        "clear" => Control::clear(),
        "move" => Control::move_cursor(int(1), int(2)),
        "move_to_column" => Control::move_to_column(int(1) as usize, int(2)),
        "move_to" => Control::move_to(int(1) as usize, int(2) as usize),
        "show_cursor" => Control::show_cursor(int(1) == 1),
        "alt_screen" => Control::alt_screen(int(1) == 1),
        "title" if w[1] == "hello" => Control::title("hello"),
        "title" => Control::title(&unhex(w[1])),
        "codes" => Control::new(w[1..].iter().map(|code| {
            let (name, n) = code.split_once(':').unwrap_or((code, "0"));
            let n: usize = n.parse().unwrap();
            match name {
                "carriage_return" => ControlCode::CarriageReturn,
                "erase_in_line" => ControlCode::EraseInLine(n),
                "cursor_up" => ControlCode::CursorUp(n),
                "cursor_down" => ControlCode::CursorDown(n),
                "cursor_forward" => ControlCode::CursorForward(n),
                "cursor_backward" => ControlCode::CursorBackward(n),
                "cursor_move_to_column" => ControlCode::CursorMoveToColumn(n),
                "enable_alt_screen" => ControlCode::EnableAltScreen,
                "disable_alt_screen" => ControlCode::DisableAltScreen,
                "show_cursor" => ControlCode::ShowCursor,
                "hide_cursor" => ControlCode::HideCursor,
                other => panic!("unknown code {other}"),
            }
        })),
        other => panic!("unknown control {other}"),
    }
}

/// Run one golden record with fast-rich and return its encoded output.
fn run(op: &str, args: &str, input: &str) -> String {
    let a: Vec<&str> = args.split(' ').collect();
    let num = |i: usize| a[i].parse::<usize>().unwrap();
    match op {
        "line" => enc_spans(&[Span::line()]),
        "split_lines" => enc_lines(&Segment::split_lines(&dec_spans(input))),
        "split_lines_terminator" => {
            let result = Segment::split_lines_terminator(&dec_spans(input));
            let lines: Vec<Vec<Span>> = result.iter().map(|(l, _)| l.clone()).collect();
            let flags: String = result
                .iter()
                .map(|(_, nl)| if *nl { 't' } else { 'f' })
                .collect();
            format!(
                "{}|{}",
                enc_lines(&lines),
                if flags.is_empty() { "-" } else { &flags }
            )
        }
        "split_and_crop_lines" => enc_lines(&Segment::split_and_crop_lines(
            &dec_spans(input),
            num(0),
            style_arg(a[3]),
            flag(a[1]),
            flag(a[2]),
        )),
        "get_line_length" => Segment::get_line_length(&dec_spans(input)).to_string(),
        "simplify" => enc_spans(&Segment::simplify(&dec_spans(input))),
        "strip_links" => enc_spans(&Segment::strip_links(&dec_spans(input))),
        "strip_styles" => enc_spans(&Segment::strip_styles(&dec_spans(input))),
        "remove_color" => enc_spans(&Segment::remove_color(&dec_spans(input))),
        "filter_control" => enc_spans(&Segment::filter_control(&dec_spans(input), flag(a[0]))),
        "apply_style" => enc_spans(&Segment::apply_style(
            &dec_spans(input),
            style_arg(a[0]),
            style_arg(a[1]),
        )),
        "divide" => {
            let cuts: Vec<usize> = if args == "-" {
                Vec::new()
            } else {
                args.split(',').map(|c| c.parse().unwrap()).collect()
            };
            enc_lines(&Segment::divide(&dec_spans(input), cuts))
        }
        "split_cells" => {
            let span = dec_spans(input).remove(0);
            let (x, y) = span.split_cells(num(0));
            enc_spans(&[x, y])
        }
        "get_shape" => {
            let (w, h) = Segment::get_shape(&dec_lines(input));
            format!("{w},{h}")
        }
        "adjust_line_length" => enc_spans(&Segment::adjust_line_length(
            &dec_spans(input),
            num(0),
            style_arg(a[2]),
            flag(a[1]),
        )),
        "set_shape" | "align_top" | "align_middle" | "align_bottom" => {
            let lines = dec_lines(input);
            let width = num(0);
            let height = (a[1] != "-").then(|| num(1));
            let style = style_arg(a[2]);
            let new_lines = flag(a[3]);
            let out = match op {
                "set_shape" => Segment::set_shape(&lines, width, height, style, new_lines),
                "align_top" => Segment::align_top(&lines, width, height.unwrap(), style, new_lines),
                "align_middle" => {
                    Segment::align_middle(&lines, width, height.unwrap(), style, new_lines)
                }
                _ => Segment::align_bottom(&lines, width, height.unwrap(), style, new_lines),
            };
            enc_lines(&out)
        }
        "control" => hex(&control(args).to_string()),
        "strip_control_codes" => hex(&strip_control_codes(&unhex(input))),
        "escape_control_codes" => hex(&escape_control_codes(&unhex(input))),
        other => panic!("unknown op {other}"),
    }
}

#[test]
fn segment_helpers_match_rich() {
    let mut count = 0;
    let mut failures = Vec::new();
    for line in GOLDEN.lines().filter(|l| !l.starts_with("# ")) {
        let f: Vec<&str> = line.split(" ; ").collect();
        let (op, args, input, want) = (f[0], f[1], f[2], f[3]);
        let got = run(op, args, input);
        if got != want {
            failures.push(format!(
                "{op}({args}) on {input}:\n  got  {got}\n  rich {want}"
            ));
        }
        count += 1;
    }
    assert!(
        failures.is_empty(),
        "{} of {count} differ:\n{}",
        failures.len(),
        failures[..failures.len().min(10)].join("\n")
    );
    assert_eq!(count, 1696);
}

#[test]
fn control_prints_only_its_escape() {
    let console = Console::capture();
    console.print_renderable(&Control::move_to(2, 1));
    console.print_renderable(&Control::new([]));
    assert_eq!(console.get_captured_output(), "\x1b[2;3H");
    assert!(Control::home().span().is_control());
    assert_eq!(Control::title("t").span().cell_length(), 0);
}
